        for c in range(w):
            if grid[r][c] != bg:
                points.setdefault(grid[r][c], []).append((r, c))

    for color, pts in points.items():
        for i, (r1, c1) in enumerate(pts):
            for r2, c2 in pts[i + 1:]:
                dr, dc = r2 - r1, c2 - c1
                if dr == 0 or abs(dr) != abs(dc):
                    continue
                slope = 1 if dc / dr > 0 else -1
                r, c = (r1, c1) if r1 < r2 else (r2, c2)
                while r >= 0 and 0 <= c < w:
