def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max({v for row in grid for v in row},
             key=lambda v: sum(row.count(v) for row in grid))

    # Find diagonal runs and extend the run from the end with more room
    # before reaching the grid boundary.
    for dr, dc in ((1, 1), (1, -1)):
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == bg:
                    continue
                pr, pc = r - dr, c - dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue

                run = []
                rr, cc = r, c
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    run.append((rr, cc))
                    rr += dr
                    cc += dc
                if len(run) < 2:
                    continue

                r1, c1 = run[0]
                r2, c2 = run[-1]

                def room(r, c, sr, sc):
                    n = 0
                    r, c = r + sr, c + sc
                    while 0 <= r < h and 0 <= c < w:
                        if grid[r][c] != bg:
                            break
                        n += 1
                        r, c = r + sr, c + sc
                    return n

                back = room(r1, c1, -dr, -dc)
                forward = room(r2, c2, dr, dc)
                if back >= forward:
                    rr, cc, sr, sc = r1 - dr, c1 - dc, -dr, -dc
                else:
                    rr, cc, sr, sc = r2 + dr, c2 + dc, dr, dc

                while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == bg:
                    out[rr][cc] = color
                    rr += sr
                    cc += sc
    return out
